import React from 'react';
import { BrowserRouter, Routes, Route, Link } from 'react-router-dom';

import Home         from './pages/Home';
import Login        from './pages/Login';
import Register     from './pages/Register';
import OrganizerDash from './features/dashboard/organizer/OrganizerDashboard';
import AttendeeDash  from './features/dashboard/attendee/AttendeeDashboard';
import ExploreEvents from './features/explore/ExploreEvents';

export default function App() {
  return (
    <BrowserRouter>
      <nav style={{ padding: '1rem', background: '#111' }}>
        <Link to="/"        style={{ margin: '0 1rem', color:'#fff' }}>Home</Link>
        <Link to="/explore" style={{ margin: '0 1rem', color:'#fff' }}>Explore Events</Link>
        <Link to="/login"   style={{ margin: '0 1rem', color:'#fff' }}>Login</Link>
        <Link to="/register"style={{ margin: '0 1rem', color:'#fff' }}>Register</Link>
      </nav>

      <Routes>
        <Route path="/"          element={<Home />} />
        <Route path="/explore"   element={<ExploreEvents />} />
        <Route path="/login"     element={<Login />} />
        <Route path="/register"  element={<Register />} />
        <Route path="/organizer/dashboard" element={<OrganizerDash />} />
        <Route path="/attendee/dashboard"  element={<AttendeeDash  />} />
      </Routes>
    </BrowserRouter>
  );
}
